import{_ as a,H as e,f as r,i as t}from"./chunks/framework.Cvt1eIE0.js";const _=JSON.parse('{"title":"PIGLIN KING 第六巻 永遠の黄金王","description":"","frontmatter":{"title":"PIGLIN KING 第六巻 永遠の黄金王","outline":"deep"},"headers":[],"relativePath":"story/6-1.md","filePath":"story/6-1.md"}'),o={name:"story/6-1.md"};function i(n,p,h,l,s,d){return e(),r("div",null,[...p[0]||(p[0]=[t('<h1 id="piglin-king" tabindex="-1">PIGLIN KING <a class="header-anchor" href="#piglin-king" aria-label="Permalink to &quot;PIGLIN KING&quot;">​</a></h1><h2 id="第六巻-永遠の黄金王" tabindex="-1">第六巻 永遠の黄金王 <a class="header-anchor" href="#第六巻-永遠の黄金王" aria-label="Permalink to &quot;第六巻 永遠の黄金王&quot;">​</a></h2><hr><h1 id="第一章-変わらぬもの" tabindex="-1">第一章 変わらぬもの <a class="header-anchor" href="#第一章-変わらぬもの" aria-label="Permalink to &quot;第一章 変わらぬもの&quot;">​</a></h1><p>王国歴五十五年。</p><p>春。</p><p>王宮の庭園に、今年もグロウベリーが花をつけた。</p><p>植えた者の名など、もう誰も覚えていない。それでも花は咲く。毎年、変わらず、同じ場所で、同じ色で。咲くことが義務ではなく、ただの喜びであるかのように。</p><p>光の粒が、蔓の先で丸く実を結び、風もないのに、わずかに揺れている。</p><p>「いたたたた……。」</p><p>スターリンがベンチから立ち上がろうとして、盛大に顔をしかめた。</p><p>白くなった顎鬚。</p><p>節くれ立った大きな手。</p><p>それでも体格だけは立派な、「大きな老人」。</p><p>人間ならとっくに動けなくなっている歳だが、黄金の冠がもたらす『世界の調和の加護』が、三人の肉体にまだかすかな活力を与えているようだった。</p><p>「腰か。」</p><p>「うるせぇ。」</p><p>オーレックスは紅茶を一口含んだ。温かかった。侍女が毎朝欠かさず淹れてくれる。その小さな習慣だけで、朝が穏やかになる気がした。</p><p>「昔はエンダードラゴンに向かって走っていった男が。」</p><p>「比べるな。あれは四十年前だ。」</p><p>「四十二年前だけどね。」</p><p>ピックバーグが本のページから目を離さずに訂正した。</p><p>眼鏡が、以前の細い金縁から、黒縁の分厚いものに変わっていた。白髪は「増えた」という段階を通り越し、髪全体が白になっていた。しかし、その奥の目だけは――遺跡の罠を一瞬で見抜いた、あの鋭い目だけは――まったく変わっていなかった。</p><p>「正確に言うな。」</p><p>「事実は事実だよ。」</p><p>「お前はそういうとこだぞ。」</p><p>「どういうとこ？」</p><p>「全部正確に覚えてるとこだ。」</p><p>「それの何が悪い。」</p><p>「悔しい。」</p><p>「それが悔しいの？」</p><p>三人は笑った。</p><p>笑い始めるのが誰からかも、もう分からなかった。誰かが笑えば、全員が笑う。あの路地裏から、あの砦から、ずっとそうだった。</p><p>変わらないものが、確かにある。</p><p>それが、何より嬉しかった。</p><hr><p>庭園の片隅に、石のベンチがある。</p><p>縁が、五十年の歳月で少し丸みを帯びていた。ここでオーレックスは何度お茶を飲んだろう。何度本を読んだろう。何度誰かと笑い合っただろう。</p><p>記憶には形がない。</p><p>しかし、石には、形が刻まれている。</p><p>長く座り続けた人間の重さが、石に少しずつ染み込んでいく。そうして、記憶は場所になる。</p><p>「あの子、今頃何歳になったかな。」</p><p>オーレックスは呟いた。</p><p>「どの子？」</p><p>スターリンが首を傾ける。</p><p>「昔、ここで花をくれた子。」</p><p>ずいぶん昔、小さな女の子が走ってきて、グロウベリーの花を一輪差し出した。「王さま、プレゼント！」と言いながら。あの笑顔の光が、今も庭のどこかに溶け込んでいる気がした。</p><p>「もう大人になってる。子供がいてもおかしくない。」</p><p>「そうか。早いな。」</p><p>「そうだね。」</p><p>早い、と言いながら、五十年という歳月に早いも遅いもないのだと、三人はもう知っていた。</p><p>ただ、流れる。止まらない。それだけだ。</p><p>「痛みが引いた！」</p><p>スターリンが立ち上がった。得意げに胸を張った。</p><p>「君、腰が痛いんじゃなかったの？」</p><p>「痛いには痛い。でも孫たちが来たら立てた。」</p><p>「それ、腰より心の問題じゃない？」</p><p>「心が体を動かすんだ！」</p><p>「……確かに一理ある。」</p><p>ピックバーグは渋々認めた。</p><p>スターリンは嬉しそうに笑って、庭を横切った。子供たちが集まってくる。アウレルの子、フローラの子、みんながスターリンの周りに群がる。木の剣が振り回される。大きな笑い声が庭を満たす。</p><p>「スターリンおじちゃん、強い！」</p><p>「当たり前だ！世界一強いんだ！」</p><p>「本当に？」</p><p>「本当だ！ただし今は腰が痛い！」</p><p>「じゃあ弱い！」</p><p>「うるさい！」</p><p>庭に、笑い声が溢れた。</p><p>オーレックスは、その光景を眺めながら静かに笑った。</p><p>ここまで来た。ここまで、みんなで来た。</p><p>その事実だけで、胸がいっぱいになることが、年を取るほど増えてきた。</p><hr><h1 id="第二章-受け継がれるもの" tabindex="-1">第二章 受け継がれるもの <a class="header-anchor" href="#第二章-受け継がれるもの" aria-label="Permalink to &quot;第二章 受け継がれるもの&quot;">​</a></h1><p>「父上！」</p><p>庭園に青年が駆け込んできた。</p><p>第一王子。アウレル・ゴールドタスク。</p><p>三十代を迎え、黄金王の息子らしく、すらりとした体格に育っていた。母リリアの穏やかな目と、父オーレックスの黄金の牙を受け継いだ、王子だった。</p><p>「今日の訓練が終わりました。親衛隊長に三本中二本勝てました。」</p><p>「お疲れ様。上出来だ。」</p><p>「スターリンおじちゃん、見てましたか！」</p><p>スターリンはにやりとした。</p><p>「見てた見てた。ただ……あの三本目の剣筋は俺の教えと違う。誰に習った。」</p><p>「師匠に内緒で別の訓練をしました。」</p><p>「正直に言えるのは立派だ。」</p><p>スターリンの目が嬉しそうに細くなった。</p><p>「右利きの相手が癖で右側に重心をかける瞬間を狙う剣術です。」</p><p>「……悪くない。教えた奴を見せてみろ。俺がさらに磨いてやる。」</p><p>「ありがとうございます！」</p><p>駆け出すアウレルの背中を見ながら、オーレックスは微笑んだ。</p><p>あの子は、どんどん強くなる。</p><p>そして、いつか。</p><p>「そろそろか。」</p><p>オーレックスは呟いた。</p><p>スターリンが聞き返す。「何が？」</p><p>「冠のことだ。」</p><p>短い沈黙が流れた。</p><p>庭園の空気が、わずかに変わった。花は変わらず揺れていたが、三人の間に、静かに重たいものが積もった。</p><p>「……まだ早い。」スターリンは言った。「まだ早い。」</p><p>「うん。」</p><p>「もう少し、だな。もう少し。」</p><p>誰も、その先を続けなかった。</p><hr><p>その夜。</p><p>オーレックスは一人、王座の間にいた。</p><p>蝋燭の明かりが一本。 その光の中に、黄金の冠。</p><p>右手を伸ばした。指先が、縁に触れた。</p><p>軽かった。</p><p>素材は金なのに、五十年経っても、これが変わらない。</p><p>冠の側面に刻まれた文字を、指の腹でなぞった。</p><p>何度なぞっただろう。何度読んだろう。</p><p>『力によって支配するな。知恵によって導け。』</p><p>若い頃は命令に聞こえた。 中年の頃は戒めに聞こえた。 今は、懇願に聞こえる。どうか忘れないでくれ、という。</p><p>『民を守る者こそ、王となる。』</p><p>民の顔が浮かんだ。橋の落ちた村で老人が泣いた時の顔。盗賊を追い払った翌朝、子供たちが笑った時の顔。戦争が終わった日、誰もが泣きながら笑っていた時の顔。全部、まだここにある。胸の中に。</p><p>『黄金とは、富ではない。希望そのものである。』</p><p>「分かってる。」</p><p>暗い部屋に、独り言が染み込んだ。</p><p>「ずっと覚えてる。でも。」</p><p>「そろそろ、渡す時が来るな。」</p><p>翌日。</p><p>アウレルを呼んだ。王座の間で、二人きり。</p><p>父と子は向かい合った。アウレルは静かに父を見ていた。緊張と、不安と、覚悟が混ざった目をしていた。若者の目だ、とオーレックスは思った。自分も、この目をしていた頃があった。</p><p>「この冠のことを、一度もちゃんと話していなかった。砦で見つけた話は知っているな。」</p><p>「もちろんです。」</p><p>「しかし。冠が何を言ったか、正確には、誰にも話したことがない。」</p><p>アウレルは少し驚いた顔をした。「スターリンも、ピックバーグも？」</p><p>「彼らはその場にいた。でも、聞こえたのは、僕だけだったと思う。」</p><p>「聞かせてください。」</p><p>オーレックスはゆっくりと話した。</p><p>あの光の声を。 砦の深い場所で聞いた言葉を。 全部を。</p><p>アウレルは黙って聞いていた。</p><p>「『黄金とは、富ではない。希望そのものである。』」</p><p>最後の一節を繰り返した後、部屋に沈黙が落ちた。蝋燭の芯が小さく爆ぜた。</p><p>「父上。冠を受け取る準備は、できています。でも。急がなくていいです。」</p><p>「……お前が言うか。」</p><p>「はい。私はまだ、父上から学ぶことがあります。もう少し、先生でいてください。」</p><p>オーレックスはしばらく黙っていた。</p><p>蝋燭の炎が、二人の影を壁に大きく映した。</p><p>「ありがとう。」</p><p>たった三文字。だが、その三文字に入り切らないものを、アウレルは分かっていた。父親のそういうところを、子供は黙って学ぶ。</p><p>「……父上。」</p><p>アウレルが少し俯いた。</p><p>「私も、ありがとうございます。こんな父のもとに生まれて、幸せです。」</p><p>二人はしばらく、同じ冠を見ていた。</p><p>父と子の視線が、黄金の上で静かに重なった。</p><hr><h1 id="第三章-黄金時代の午後" tabindex="-1">第三章 黄金時代の午後 <a class="header-anchor" href="#第三章-黄金時代の午後" aria-label="Permalink to &quot;第三章 黄金時代の午後&quot;">​</a></h1><p>王国歴六十年。</p><p>春。</p><p>PIGLIN KINGDOMは、建国以来最大の繁栄を迎えていた。</p><p>王立大学の講堂では、若い学者たちが夜遅くまで議論していた。机の上には、ピックバーグが著した古代文明の解読書が何冊も積まれていた。いつか彼は言った。「本は読まれることで初めて完成する」と。今、それが証明されていた。</p><p>鉄道網が大陸の端まで延び、汽車の汽笛が玄武岩デルタに響くようになっていた。かつて橋一本で孤立していた村は、今では鉄道の駅を持つ町になっていた。あの橋は今も架かっている。ピックバーグが設計し、スターリンが岩を運び、オーレックスが木を切った、あの橋が。</p><p>王立博物館には、「忘れられた砦」から発掘された品々が並んでいた。古代ヴォールト文明の罠の設計図。そして、初代黄金王が愛読した古い本の複製。</p><p>歴史家たちはこの時代を「黄金時代」と呼んだ。</p><p>当の本人は。</p><p>「また書類が増えた。」</p><p>机に突っ伏していた。</p><p>「五十年以上もやってて今さら？」</p><p>リリアが笑った。</p><p>「だって。僕は元々、こういう人間じゃなかったから。」</p><p>「どういう人間だったんですか。」</p><p>「本を読んで、遺跡を探検して、溶岩の音を聞きながらぼうっとしていたい人間。」</p><p>「それは知っています。」</p><p>「だから、たまに、ぼうっとしたくなる。」</p><p>「では、お茶にしましょう。ぼうっとしながら。」</p><p>「うん。それが一番いい。」</p><p>そんな二人を見て、スターリンが庭から叫んだ。</p><p>「いちゃいちゃしてないで書類終わらせろ！」</p><p>「うるさい。」</p><p>ピックバーグも庭から叫んだ。「君もうるさい。」</p><p>「どっちもうるさい！」</p><p>庭に笑い声が響いた。</p><p>「平和ってのは。」</p><p>スターリンが空を仰ぎ、満足そうに呟いた。</p><p>「いいもんだなぁ。」</p><p>「本当に。」</p><p>四人の声が、重なった。</p><p>その言葉を、同時に、自然に、言えること。それがもう、十分すぎる答えだった。</p><hr><h1 id="第四章-夜のバルコニー" tabindex="-1">第四章 夜のバルコニー <a class="header-anchor" href="#第四章-夜のバルコニー" aria-label="Permalink to &quot;第四章 夜のバルコニー&quot;">​</a></h1><p>王国歴六十年。</p><p>ある夜。</p><p>バルコニーに、三人がいた。</p><p>星が出ていた。</p><p>ネザーでは珍しい、澄んだ夜だった。</p><p>「ここまで来るとは思わなかった。」</p><p>スターリンが言った。「建国した時。こんな未来になるとは。」</p><p>「思わなかったね。」</p><p>「俺はさ。」</p><p>スターリンは続けた。珍しく、静かな声で。</p><p>「昔から死が近かった。毎日戦ってたから。長生きするって感覚がなかった。」</p><p>「うん。」</p><p>「だから、今こうして生きてると、なんか……意外な感じがする。」</p><p>「悪い意味じゃなく？」</p><p>「悪い意味じゃない。ただ。いい意味で意外。」</p><p>ピックバーグが星を見上げたまま言った。</p><p>「僕は、友達ができるとは思っていなかった。」</p><p>「知ってる。砦で会った最初、お前、俺たちのこと興味なさそうだったしな。」</p><p>「興味はあった。ただ、友達という概念が、あまりピンとこなかった。」</p><p>「今は？」</p><p>少し間があった。</p><p>「今は。分かる。五十年かかったけど、やっと分かった。」</p><p>「遅い。」</p><p>「遅いね。でも、確かに、学んだ。」</p><p>「俺はあの日の路地でもう分かってた。」</p><p>「分かってた？こいつら友達になるな、って。」</p><p>「……なんで？」</p><p>「なんとなく。」</p><p>「なんとなくで友達になるな。」</p><p>「でも、そうなった。」</p><p>三人は笑った。</p><p>しばらくして。</p><p>オーレックスが静かに言った。</p><p>「アウレルも立派になった。そろそろかもしれない。次の時代が。」</p><p>スターリンは少し黙った。</p><p>「……まだ早い。」</p><p>「うん。もう少し、だな。もう少し。」</p><p>「もう少し。」</p><p>三人は繰り返した。</p><p>誰も、「終わり」という言葉を使わなかった。</p><p>それでも、三人とも、同じことを考えていた。</p><p>その事実が、今夜の星を、少しだけ眩しくしていた。</p>',222)])])}const u=a(o,[["render",i]]);export{_ as __pageData,u as default};
